import { profile as p } from "../data/profile.js";
import { boot, pageHero, scene, lazyScene } from "./shared.js";
import { esc, sortedPublications } from "../components/utils.js";
import { icon } from "../components/icons.js";
import { pubCard } from "../components/pubCard.js";
import { revealCards } from "../animations/micro.js";
const d = p.diagrams.smith,
  u = p.publicationsPage;
boot(
  "publications",
  `
 ${pageHero("publications", `${scene("smith", d.aria)}<div class="smith-readout"><span>${d.frequency} <strong data-frequency>6.56</strong> ${d.units}</span><span>${d.reflection} <strong data-s11>−15.3</strong> ${d.db}</span></div><p class="diagram-caption mono">${d.caption}</p>`)}
 <section class="section container publications-section"><div class="publication-tools"><div class="filters" role="group" aria-label="${esc(u.eyebrow)}">${u.filters.map((f, i) => `<button class="filter" data-filter="${i}" aria-pressed="${i === 0}">${f}</button>`).join("")}<span class="filter-underline" aria-hidden="true"></span></div><div class="search-wrap">${icon("search")}<label class="sr-only" for="pub-search">${u.searchLabel}</label><input id="pub-search" type="search" placeholder="${u.searchPlaceholder}" autocomplete="off"></div></div><div class="results-summary"><span class="mono" id="results-count" role="status"></span><p>${u.note}</p></div><h2 class="sr-only">${u.listTitle}</h2><div id="publication-list"></div></section>
`,
);
const list = document.querySelector("#publication-list"),
  search = document.querySelector("#pub-search"),
  filters = [...document.querySelectorAll("[data-filter]")];
let active = 0;
function underline() {
  const button = filters[active],
    line = document.querySelector(".filter-underline");
  line.style.width = `${button.offsetWidth}px`;
  line.style.left = `${button.offsetLeft}px`;
}
function render() {
  const query = search.value.trim().toLocaleLowerCase();
  const papers = sortedPublications().filter(
    (pub) =>
      (active === 0 ||
        (active === 1 && pub.type === "Journal") ||
        (active === 2 && pub.type === "Conference") ||
        (active === 3 && pub.firstAuthor)) &&
      [pub.title, pub.authors.join(" "), pub.venue].some((text) =>
        text.toLocaleLowerCase().includes(query),
      ),
  );
  document.querySelector("#results-count").textContent =
    `${String(papers.length).padStart(2, "0")} ${u.countSuffix}`;
  list.innerHTML = papers.length
    ? papers.map((pub, i) => pubCard(pub, i)).join("")
    : `<div class="empty-state"><p>${u.empty}</p><button class="button" id="reset-publications">${u.reset}</button></div>`;
  document
    .querySelector("#reset-publications")
    ?.addEventListener("click", () => {
      search.value = "";
      active = 0;
      filters.forEach((b, i) =>
        b.setAttribute("aria-pressed", String(i === 0)),
      );
      underline();
      render();
      search.focus();
    });
  revealCards(list);
}
filters.forEach((button, i) =>
  button.addEventListener("click", () => {
    active = i;
    filters.forEach((b, j) => b.setAttribute("aria-pressed", String(i === j)));
    underline();
    render();
  }),
);
search.addEventListener("input", render);
window.addEventListener("resize", underline);
document.fonts.ready.then(underline);
render();
underline();
lazyScene("smith", () => import("../animations/smith.js"), "smith");
